fn json_allows_funnel_on_https_443(value: &Value) -> bool {
    value
        .get("AllowFunnel")
        .and_then(Value::as_object)
        .is_some_and(|entries| {
            entries.iter().any(|(address, enabled)| {
                address.ends_with(":443") && enabled.as_bool() == Some(true)
            })
        })
}

